// Guard set a well-behaved automated block-use should replicate before calling useItemOn,
// in vanilla's own evaluation order. Every symbol below was verified via javap/decompile on 26.2.
// Mirrors Minecraft.tick -> handleKeybinds -> startUseItem -> MultiPlayerGameMode.useItemOn.

import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.client.multiplayer.MultiPlayerGameMode;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;

public final class VanillaCadenceBlockUse {
    // Replicates Minecraft.rightClickDelay (that field is private).
    private int useDelay;

    /** Call once per client tick, at the same phase vanilla runs handleKeybinds:
     *  after gameMode.tick() and pick(1.0F), before level.tickEntities(). */
    public void onClientTick(Minecraft mc) {
        if (this.useDelay > 0) {
            this.useDelay--;          // Minecraft.tick(): 'if (rightClickDelay > 0) rightClickDelay--;'
        }

        LocalPlayer player = mc.player;
        MultiPlayerGameMode gameMode = mc.gameMode;
        ClientLevel level = mc.level;
        if (player == null || gameMode == null || level == null) {
            return;
        }
        // (i) handleKeybinds is not called at all while a screen or overlay is up.
        if (mc.gui.screen() != null || mc.gui.overlay() != null) {
            return;
        }
        // LocalPlayer.tick() wraps everything in this; nothing is synced before it.
        if (!player.connection.hasClientLoaded()) {
            return;
        }
        // (iv) startUseItem returns immediately while mining, and does NOT arm the delay.
        if (gameMode.isDestroying()) {
            return;
        }
        // (v) steering a boat.
        if (player.isHandsBusy()) {
            return;
        }
        // (ii)/(iii) hold path: vanilla never re-uses while an item is being used.
        if (player.isUsingItem()) {
            return;
        }
        // (iii) the 4-tick throttle.
        if (this.useDelay != 0) {
            return;
        }
        // BLOCK branch only. hitResult was refreshed by pick(1.0F) earlier this tick.
        if (mc.hitResult == null
                || mc.hitResult.getType() != HitResult.Type.BLOCK
                || !(mc.hitResult instanceof BlockHitResult blockHit)) {
            return;
        }
        // (vii) useItemOn's own early-out; checking it here avoids a wasted delay arm.
        if (!level.getWorldBorder().isWithinBounds(blockHit.getBlockPos())) {
            return;
        }

        InteractionHand hand = InteractionHand.MAIN_HAND;
        ItemStack held = player.getItemInHand(hand);
        // (vi) feature-flag gate.
        if (!held.isItemEnabled(level.enabledFeatures())) {
            return;
        }
        // (viii) spectator: performUseItemOn short-circuits to CONSUME, so the packet is pure noise.
        if (gameMode.isSpectator()) {
            return;
        }
        // (ix) sneak + non-empty hands suppresses the block interaction in vanilla.
        if (player.isSecondaryUseActive() && !held.isEmpty()) {
            return;
        }
        // (xi) cooldown blocks the item's own useOn leg.
        if (player.getCooldowns().isOnCooldown(held)) {
            return;
        }

        // Arm BEFORE the call, exactly like startUseItem: the cost is paid on attempt, not success.
        this.useDelay = 4;

        InteractionResult result = gameMode.useItemOn(player, hand, blockHit);
        if (result instanceof InteractionResult.Success success
                && success.swingSource() == InteractionResult.SwingSource.CLIENT) {
            player.swing(hand);
        }
    }

    /** Vanilla releases the in-progress use when the key goes up; mirror it when your macro stops. */
    public void onStop(Minecraft mc) {
        if (mc.player != null && mc.gameMode != null && mc.player.isUsingItem()) {
            mc.gameMode.releaseUsingItem(mc.player);   // sends the release packet, then player.releaseUsingItem()
        }
    }
}
